<?php
header('Access-Control-Allow-Origin: *');header('Access-Control-Allow-Methods: GET, POST, OPTIONS');header('Access-Control-Allow-Headers: Content-Type, Authorization');header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']==='OPTIONS'){exit;}
require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/rut.php';
try{$pdo=getDB();$input=$_SERVER['REQUEST_METHOD']==='POST'?(json_decode(file_get_contents('php://input'),true)?:[]):$_GET;$rut=normalizarRut(trim((string)($input['rut']??'')));if(!validarRut($rut)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'RUT inválido']);exit;}$q=$pdo->prepare('SELECT id,rut,nombre,telefono,email FROM duenos WHERE rut=:rut');$q->execute([':rut'=>$rut]);$dueno=$q->fetch();if(!$dueno){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Perfil no encontrado']);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$nombre=trim((string)($input['nombre']??''));$telefono=trim((string)($input['telefono']??''));$email=trim((string)($input['email']??''));if(!$nombre||!$telefono||!filter_var($email,FILTER_VALIDATE_EMAIL)){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Revisa nombre, teléfono y correo']);exit;}$params=[':n'=>$nombre,':t'=>$telefono,':e'=>$email,':id'=>(int)$dueno['id']];$sql='UPDATE duenos SET nombre=:n,telefono=:t,email=:e';$password=trim((string)($input['password']??''));if($password!==''){if(strlen($password)<8){http_response_code(422);echo json_encode(['success'=>false,'message'=>'La contraseña debe tener 8 caracteres']);exit;}$sql.=',password=:p';$params[':p']=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=:id';$pdo->prepare($sql)->execute($params);$dueno['nombre']=$nombre;$dueno['telefono']=$telefono;$dueno['email']=$email;}echo json_encode(['success'=>true,'perfil'=>$dueno]);}catch(Throwable $e){error_log('API perfil: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Error del servidor']);}
